def d4(shape):
 out=[]
 for k in range(4):
  pts=set(shape)
  for _ in range(k): pts={(-c,r) for r,c in pts}
  for refl in range(2):
   p={(r,-c) if refl else (r,c) for r,c in pts}
   mr=min(r for r,c in p); mc=min(c for r,c in p)
   p={(r-mr,c-mc) for r,c in p}
   if p not in out:out.append(p)
 return out
