def transforms(sh):
 result=[]
 for k in range(4):
  pts=set(sh)
  for _ in range(k): pts={(-c,r) for r,c in pts}
  for flip in [False,True]:
   p={(r,-c) if flip else (r,c) for r,c in pts}
   mr=min(r for r,c in p); mc=min(c for r,c in p)
   p=frozenset((r-mr,c-mc) for r,c in p)
   if p not in result: result.append(p)
 return result
